export const meta = {
  name: 'ajcr-t3-signature-map',
  description: 'Map exact signatures and proof idioms needed for T3 DivisorDatumSectionOfClass',
  phases: [{ title: 'Read', detail: 'six parallel readers over the T3 dependency cone' }],
}

const ROOT = '/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild'

const SCHEMA = {
  type: 'object',
  properties: {
    declarations: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          file: { type: 'string' },
          line: { type: 'integer' },
          signature: { type: 'string', description: 'full Lean signature, verbatim including implicit args, instance args, and universe notes' },
          notes: { type: 'string', description: 'what it does, hypotheses that matter (esp. Noetherian), definitional unfolding behavior' },
        },
        required: ['name', 'file', 'signature'],
      },
    },
    idioms: { type: 'array', items: { type: 'string' }, description: 'proof idioms/patterns present in these files that T3 will reuse, with file:line' },
    hazards: { type: 'array', items: { type: 'string' }, description: 'traps: Noetherian hypotheses, defeq walls, universe issues, deprecated forms' },
  },
  required: ['declarations', 'idioms', 'hazards'],
}

const READERS = [
  {
    key: 'glued-sheaf',
    files: ['AlgebraicJacobian/Cohomology/GluedSheafDatum.lean', 'AlgebraicJacobian/Cohomology/GluedSheaf.lean', 'AlgebraicJacobian/Cohomology/GluedSheafClass.lean'],
    want: 'structure BasicOpenCocycleDatum (ALL fields, verbatim, incl. index/pieces/unit/cocycle fields and instance assumptions), gluedSubmodule, component (and every lemma about component: component_ratio, restriction, injectivity), cechPicClass (its exact definition and every lemma relating it to unitsH1/CechPic classes), and any existing lemma producing an element of gluedSubmodule from local data',
  },
  {
    key: 'sections-to-divisors',
    files: ['AlgebraicJacobian/Picard/SectionsToDivisorsClass.lean', 'AlgebraicJacobian/Picard/Pic0RankOneFibrePresentedProducerSectionDivEq.lean'],
    want: 'sectionLocalEquations and sectionLocalEquationsOfFibrewiseRegular (exact signatures + what cover/sigma/subordination args mean), the gluedSubordUnit / component_ratio_eq subordination-unit toolkit (every lemma), sectionLocalEquations_divEq_of_same_section and pullback_sectionLocalEquationsOfFibrewiseRegular_divEq_sectionsMapTop, and every lemma computing picClass or DivEq of sectionLocalEquations',
  },
  {
    key: 'datum-inverse',
    files: ['AlgebraicJacobian/Picard/DivisorDatumInverse.lean', 'AlgebraicJacobian/Picard/DivisorClass.lean'],
    want: 'LocalEquations structure (all fields), DivEq definition and all its lemmas (transitivity/symmetry/pullback), picClass of LocalEquations, and in DivisorDatumInverse: canonSection, canon_matching (line ~248), divEq_sectionLocalEquations_canonSection (line ~320) — the full proof idiom of how a section is glued from local equations and proved DivEq, verbatim structure of those proofs (what tactic skeleton, which sheaf-axiom API is used: TopCat.Sheaf.existsUnique_gluing? Scheme.presheaf? which)',
  },
  {
    key: 'cech-cohomology',
    files: ['AlgebraicJacobian/Picard/Pic.lean', 'AlgebraicJacobian/Picard/CechH1.lean', 'AlgebraicJacobian/Picard/UnitsCocycle.lean'],
    want: 'CechPic definition, CechPic.mk_eq_mk_iff (line ~75 of Pic.lean) exact statement, unitsH1 and its quotient structure (PresheafOfGroups.H1, UnitsCocycle.lean ~159), IsCohomologous definition, OneCocycle.isCohomologous_iff_evInf (CechH1.lean ~293) exact statement, refinement/unitsRes maps and every lemma moving a class to a common refinement, and how a 0-cochain of units is extracted from cohomologous cocycles',
  },
  {
    key: 'rank-one-local-divisor',
    files: ['AlgebraicJacobian/Picard/Pic0RankOneLocalDivisor.lean', 'AlgebraicJacobian/Picard/Pic0RankOnePresentation.lean'],
    want: 'sectionLocalEquationsOfDatumSectionBaseChange (Presentation.lean ~318) and its divEq_of_unit consumer (LocalDivisor.lean ~216): exact signatures, WHERE the [IsNoetherianRing B] hypothesis enters and whether the underlying engine existsUnique_unit_tensorAway_rankOne_generators (~165) needs it; also datumSectionBaseChange, and every lemma about D.baseChange / cechPicClass_baseChange; report precisely which lemmas would need Noetherian stripped for a non-Noetherian B version',
  },
  {
    key: 'glue-idiom',
    files: ['AlgebraicJacobian/Picard/DivisorFamilyAffThetaTyping.lean', 'AlgebraicJacobian/Cohomology/GluedSheaf.lean'],
    want: 'the glueThetaZero sheaf-axiom gluing idiom: exact declaration, how compatible local sections on an open cover of an open subscheme are glued (which mathlib sheaf-condition API), and any general-purpose glue lemma reusable for gluing alpha-corrected local equations over pieces; also in GluedSheaf.lean how membership in gluedSubmodule is proven (constructors, mem_ lemmas)',
  },
]

phase('Read')
const results = await parallel(READERS.map(r => () =>
  agent(
    `You are mapping Lean 4 source for a proof-engineering task in the repo ${ROOT} (project AlgebraicJacobian, a Jacobian/Picard formalization over mathlib).\n\n` +
    `Read these files COMPLETELY (they are each 100-600 lines):\n${r.files.map(f => ROOT + '/' + f).join('\n')}\n\n` +
    `Extract: ${r.want}\n\n` +
    `Report EVERY declaration relevant to that ask with its VERBATIM signature (copy the source text of the statement, including binders, instance brackets, and hypotheses) and 1-3 sentences of notes. Also list proof idioms (how the nontrivial proofs in these files are structured — which API calls do the heavy lifting) and hazards (Noetherian or finiteness hypotheses, defeq-sensitive definitions, quotient types needing choice of representative). Be exhaustive within the listed files; do not summarize away hypotheses. Line numbers matter.`,
    { label: `read:${r.key}`, phase: 'Read', schema: SCHEMA, model: 'opus' }
  )
))
return Object.fromEntries(READERS.map((r, i) => [r.key, results[i]]))
